      "business": "Notion"
    },
    {
      "why": "Same monospaced micro-type accent, hairline #e5e7eb borders, and dark filled button as the only primary action",
      "business": "Vercel"
    },
    {
      "why": "Similar gradient-as-illustration philosophy — chromatic color confined to decorative washes and imagery, never on functional UI",
      "business": "Stripe"
    }
  ]
}
